TIM_TimeBaseInitTypeDef TIM_TimeBaseStructure;

/* 目标：1 秒中断一次。TIM2 时钟 72MHz
   Prescaler=7199 → 72MHz/7200 = 10kHz
   Period=9999    → 10kHz/10000 = 1Hz */
TIM_TimeBaseStructure.TIM_Prescaler = 7199;
TIM_TimeBaseStructure.TIM_Period = 9999;
TIM_TimeBaseStructure.TIM_CounterMode = TIM_CounterMode_Up;
TIM_TimeBaseStructure.TIM_ClockDivision = TIM_CKD_DIV1;
TIM_TimeBaseStructure.TIM_RepetitionCounter = 0;   /* 通用定时器必须填 0 */
TIM_TimeBaseInit(TIM2, &TIM_TimeBaseStructure);

TIM_Cmd(TIM2, ENABLE);

TIM_OCInitTypeDef TIM_OCInitStructure;

TIM_OCInitStructure.TIM_OCMode = TIM_OCMode_PWM1;
TIM_OCInitStructure.TIM_OutputState = TIM_OutputState_Enable;
TIM_OCInitStructure.TIM_Pulse = 500;          /* 初始占空比 */
TIM_OCInitStructure.TIM_OCPolarity = TIM_OCPolarity_High;
TIM_OC1Init(TIM3, &TIM_OCInitStructure);

/* 使能预装载，改占空比时无毛刺 */
TIM_OC1PreloadConfig(TIM3, TIM_OCPreload_Enable);
TIM_ARRPreloadConfig(TIM3, ENABLE);
TIM_Cmd(TIM3, ENABLE);

TIM_OCInitStructure.TIM_OCMode = TIM_OCMode_PWM1;
TIM_OCInitStructure.TIM_OutputState = TIM_OutputState_Enable;
TIM_OCInitStructure.TIM_Pulse = 250;
TIM_OCInitStructure.TIM_OCPolarity = TIM_OCPolarity_High;
TIM_OC2Init(TIM3, &TIM_OCInitStructure);

TIM_ICInitTypeDef TIM_ICInitStructure;

TIM_ICInitStructure.TIM_Channel = TIM_Channel_1;
TIM_ICInitStructure.TIM_ICPolarity = TIM_ICPolarity_Rising;
TIM_ICInitStructure.TIM_ICSelection = TIM_ICSelection_DirectTI;
TIM_ICInitStructure.TIM_ICPrescaler = TIM_ICPSC_DIV1;   /* 每次边沿都捕获 */
TIM_ICInitStructure.TIM_ICFilter = 0x0;                 /* 不滤波 */
TIM_ICInit(TIM3, &TIM_ICInitStructure);

TIM_Cmd(TIM3, ENABLE);

TIM_ICInitTypeDef TIM_ICInitStructure;

TIM_ICInitStructure.TIM_Channel = TIM_Channel_1;
TIM_ICInitStructure.TIM_ICPolarity = TIM_ICPolarity_Rising;
TIM_ICInitStructure.TIM_ICSelection = TIM_ICSelection_DirectTI;
TIM_ICInitStructure.TIM_ICPrescaler = TIM_ICPSC_DIV1;
TIM_ICInitStructure.TIM_ICFilter = 0x0;
TIM_PWMIConfig(TIM3, &TIM_ICInitStructure);

/* 选输入触发源与从模式 */
TIM_SelectInputTrigger(TIM3, TIM_TS_TI1FP1);
TIM_SelectSlaveMode(TIM3, TIM_SlaveMode_Reset);
TIM_Cmd(TIM3, ENABLE);

/* 读取：CCR1 = 周期，CCR2 = 高电平时间 */

TIM_BDTRInitTypeDef TIM_BDTRInitStructure;

TIM_BDTRInitStructure.TIM_OSSRState = TIM_OSSRState_Enable;
TIM_BDTRInitStructure.TIM_OSSIState = TIM_OSSIState_Enable;
TIM_BDTRInitStructure.TIM_LOCKLevel = TIM_LOCKLevel_1;
TIM_BDTRInitStructure.TIM_DeadTime = 0x0A;          /* 死区时间 */
TIM_BDTRInitStructure.TIM_Break = TIM_Break_Disable;
TIM_BDTRInitStructure.TIM_BreakPolarity = TIM_BreakPolarity_High;
TIM_BDTRInitStructure.TIM_AutomaticOutput = TIM_AutomaticOutput_Enable;
TIM_BDTRConfig(TIM1, &TIM_BDTRInitStructure);

TIM_OCInitTypeDef TIM_OCInitStructure;

TIM_OCStructInit(&TIM_OCInitStructure);
TIM_OCInitStructure.TIM_OCMode = TIM_OCMode_PWM1;
TIM_OCInitStructure.TIM_OutputState = TIM_OutputState_Enable;   /* 必须改，否则无输出 */
TIM_OCInitStructure.TIM_Pulse = 500;
TIM_OCInitStructure.TIM_OCPolarity = TIM_OCPolarity_High;
TIM_OC1Init(TIM3, &TIM_OCInitStructure);

TIM_ICInitTypeDef TIM_ICInitStructure;

TIM_ICStructInit(&TIM_ICInitStructure);
TIM_ICInitStructure.TIM_Channel = TIM_Channel_2;   /* 改到通道 2 */
TIM_ICInit(TIM3, &TIM_ICInitStructure);

TIM_Cmd(TIM3, ENABLE);    /* 启动 */
/* ... */
TIM_Cmd(TIM3, DISABLE);   /* 停止 */

/* TIM1 输出 PWM 的完整收尾 */
TIM_Cmd(TIM1, ENABLE);
TIM_CtrlPWMOutputs(TIM1, ENABLE);   /* 少了这行引脚没波形 */

TIM_ITConfig(TIM2, TIM_IT_Update, ENABLE);

/* NVIC 也要配，否则中断进不来 */
NVIC_InitStructure.NVIC_IRQChannel = TIM2_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 0x01;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0x01;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

TIM_Cmd(TIM2, ENABLE);

/* 让 DMA 批量写 CCR1，实现任意波形 */
TIM_DMAConfig(TIM1, TIM_DMABase_CCR1, TIM_DMABurstLength_1Transfer);
TIM_DMACmd(TIM1, TIM_DMA_Update, ENABLE);

/* TIM2 用内部触发 0 作为时钟 */
TIM_ITRxExternalClockConfig(TIM2, TIM_TS_ITR0);
TIM_SelectSlaveMode(TIM2, TIM_SlaveMode_External1);

/* PA6(TIM3_CH1) 输入脉冲，每个上升沿计数 */
TIM_TIxExternalClockConfig(TIM3, TIM_TIxExternalCLK1Source_TI1,
                           TIM_ICPolarity_Rising, 0x0);
TIM_SelectSlaveMode(TIM3, TIM_SlaveMode_External1);
TIM_Cmd(TIM3, ENABLE);

/* ETR 上升沿计数，2 分频 */
TIM_ETRClockMode1Config(TIM2, TIM_ExtTRGPSC_DIV2,
                        TIM_ExtTRGPolarity_NonInverted, 0x0);
TIM_SelectSlaveMode(TIM2, TIM_SlaveMode_External1);

/* 把定时周期改为 0.5 秒 */
TIM_PrescalerConfig(TIM2, 7199, TIM_PSCReloadMode_Immediate);
TIM_SetAutoreload(TIM2, 4999);

/* PWM 输入模式下的标准配置 */
TIM_SelectInputTrigger(TIM3, TIM_TS_TI1FP1);
TIM_SelectSlaveMode(TIM3, TIM_SlaveMode_Reset);

/* TIM3 接编码器 A/B 相，四倍频 */
TIM_EncoderInterfaceConfig(TIM3, TIM_EncoderMode_TI12,
                           TIM_ICPolarity_Rising, TIM_ICPolarity_Rising);
TIM_Cmd(TIM3, ENABLE);

/* 读位置：计数器值 */
uint16_t pos = TIM_GetCounter(TIM3);

/* PWM 输入测量：每个上升沿复位计数器 */
TIM_SelectInputTrigger(TIM3, TIM_TS_TI1FP1);
TIM_SelectSlaveMode(TIM3, TIM_SlaveMode_Reset);

/* 改 PWM 频率：ARR 从 999 改为 499 */
TIM_SetAutoreload(TIM3, 499);

/* 同时按比例改占空比，否则占空比会变 */
TIM_SetCompare1(TIM3, 250);

/* ARR=999 时，CCR1=250 表示 25% 占空比 */
TIM_SetCompare1(TIM3, 250);

/* 呼吸灯：循环改占空比 */
for (uint16_t i = 0; i <= 1000; i += 10)
{
  TIM_SetCompare1(TIM3, i);
  Delay_ms(10);
}

uint16_t capture;

/* 等捕获完成 */
while (TIM_GetFlagStatus(TIM3, TIM_FLAG_CC1) == RESET)
{
}
TIM_ClearFlag(TIM3, TIM_FLAG_CC1);

capture = TIM_GetCapture1(TIM3);
/* 实际时间 = capture / (定时器时钟 / 分频) */

/* PWM 输入模式：CCR1=周期，CCR2=高电平时间 */
uint16_t period = TIM_GetCapture1(TIM3);
uint16_t high   = TIM_GetCapture2(TIM3);
/* 占空比 = high / period */

/* 轮询等待一次更新（溢出） */
while (TIM_GetFlagStatus(TIM2, TIM_FLAG_Update) == RESET)
{
}
TIM_ClearFlag(TIM2, TIM_FLAG_Update);

void TIM2_IRQHandler(void)
{
  /* 中断里用 GetITStatus，不用 GetFlagStatus */
  if (TIM_GetITStatus(TIM2, TIM_IT_Update) != RESET)
  {
    TIM_ClearITPendingBit(TIM2, TIM_IT_Update);   /* 必须清 */
    /* 用户代码 */
  }
}

void TIM2_IRQHandler(void)
{
  if (TIM_GetITStatus(TIM2, TIM_IT_Update) != RESET)
  {
    TIM_ClearITPendingBit(TIM2, TIM_IT_Update);
  }
}
